const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');
return [{ json: { ...$('Verify Signature').first().json, timestamp, signature } }];

const icp = $('GET ICP Profile').first().json.icpProfile;
const titles = Array.isArray(icp.jobTitles) && icp.jobTitles.length ? icp.jobTitles : ['Founder', 'CEO'];
const industries = Array.isArray(icp.industries) ? icp.industries : [];
const geographies = Array.isArray(icp.geographies) ? icp.geographies : [];
const industriesPart = industries.slice(0, 4).join(', ');
const geoSuffix = geographies.length ? (' in ' + geographies.slice(0, 2).join(' or ')) : '';
// Content-focused, not instructional: these are terms that actually appear
// on the pages we want (leadership/about/press pages), not meta-commentary
// about what kind of source is acceptable -- that policy already lives in
// the LLM's system prompt (DEFAULT_AGENT_PROMPTS.prospector) for its own
// extraction judgment. An earlier version of this tail ("found on any of:
// a company leadership/team/about page, a press release, or (optionally,
// not required) their LinkedIn profile") was literal instructional text
// sent AS the search query -- Tavily has no way to interpret "optionally,
// not required" as anything but more keywords to match against, which
// diluted results toward generic pages instead of pages naming real people.
const tail = ' - leadership team, about us, or press release';
// One focused search PER job title (capped at 10 to keep Tavily usage
// bounded - free tier is 1,000 searches/month) instead of one blended
// query that only ever covered the first 3 titles: a query diluted across
// many personas at once finds far fewer distinct real candidates than the
// same number of titles searched separately. Tavily: Web Search runs once
// per item n8n produces here.
const cappedTitles = titles.slice(0, 10);
return cappedTitles.map(function (title) {
  var q = title + ' at a ' + (industriesPart || 'B2B') + ' company' + geoSuffix + tail;
  return { json: { query: q } };
});

const guessCompanyFromTitle = (title) => {
  if (!title) return null;
  let mm = title.match(/^(.+?)\s*[-|]\s*Leadership(?:\s*team)?\s*$/i);
  if (mm) return mm[1].trim();
  mm = title.match(/^(?:Leadership|Team)(?:\s*team)?\s*[-|]\s*(.+)$/i);
  if (mm) return mm[1].trim();
  mm = title.match(/\|\s*([^|]+?)(?:\s+Leadership)?\s*$/i);
  if (mm && mm[1].trim().length > 1) return mm[1].trim();
  mm = title.match(/^(.+?)\s*[-|]\s*(?:Our\s*)?Team\s*$/i);
  if (mm) return mm[1].trim();
  return null;
};
const items = $input.all();
return items.map(function (item) {
  const rawResults = (item.json && item.json.results) || [];
  const enriched = rawResults.map(function (r) {
    const isLinkedInProfile = /linkedin\.com\/in\//i.test(r.url);
    let company = null, location = null;
    if (isLinkedInProfile) {
      const m2 = (r.content || '').match(/^#\s*.+\n([^\n]+)\n([^\n]+)/m);
      if (m2) { company = m2[1].trim(); location = m2[2].trim(); }
    } else {
      company = guessCompanyFromTitle(r.title);
    }
    return { title: r.title, link: r.url, isLinkedInProfile, extractedCompany: company, extractedLocation: location, snippet: (r.content || '').slice(0, 1200) };
  });
  return { json: { query: item.json.query, results: enriched } };
});

const items = $input.all();
const sig = $('Verify Signature').first().json;
const agentId = $('GET Agent Prompt (prospector)').first().json.agent.id;
return items.map(function (item) {
  const response = item.json;
  let candidates = [];
  let errorMessage = null;
  if (response.error) {
    errorMessage = 'LLM call failed: ' + (response.error.message || JSON.stringify(response.error));
  } else {
    const text = response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content;
    if (!text) {
      errorMessage = 'LLM returned no content (empty response)';
    } else {
      try {
        const withoutThoughts = text.replace(/<thought>[\s\S]*?<\/thought>/gi, '');
        const cleaned = withoutThoughts.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
        const parsed = JSON.parse(cleaned);
        candidates = Array.isArray(parsed.candidates) ? parsed.candidates : [];
      } catch (e) {
        errorMessage = 'Failed to parse LLM response as JSON: ' + e.message;
      }
    }
  }
  return { json: { icpId: sig.icpId, runId: sig.runId, orgId: sig.orgId, agentId: agentId, candidates: candidates, errorMessage: errorMessage } };
});

const items = $input.all();
const meta = items[0]?.json || {};
const seen = new Set();
const combined = [];
for (const item of items) {
  const c = item.json;
  for (const cand of (c.candidates || [])) {
    const key = (cand.sourceUrl || '') + '|' + (cand.firstName || '') + '|' + (cand.lastName || '') + '|' + (cand.company || '');
    if (!seen.has(key)) {
      seen.add(key);
      combined.push(cand);
    }
  }
}
// One query batch's LLM/parse failure never fails the whole run -- only
// surface a failure if every single batch failed AND none found candidates.
const allFailed = items.length > 0 && items.every(i => i.json.errorMessage) && combined.length === 0;
return [{ json: { icpId: meta.icpId, runId: meta.runId, orgId: meta.orgId, agentId: meta.agentId, candidates: combined, errorMessage: allFailed ? items[0].json.errorMessage : null } }];

const items = $input.all();
return items.map(function (item) {
  const raw = item.json;
  const candidate = (raw && typeof raw === 'object' && raw.candidates && typeof raw.candidates === 'object' && !Array.isArray(raw.candidates)) ? raw.candidates : raw;
  return { json: candidate };
});

const items = $input.all();
const originals = $('IF: Has Company').all();
return items.map(function (item, i) {
  const original = (originals[i] && originals[i].json) || {};
  const res = item.json || {};
  const data = res.data || {};
  let email = null;
  if (data.email && typeof data.score === 'number' && data.score >= 50) {
    email = data.email;
  }
  return { json: { ...original, email } };
});

const meta = $('Parse Candidates JSON').first().json;
const candidates = $input.first().json.candidates || [];
return [{ json: { icpId: meta.icpId, runId: meta.runId, orgId: meta.orgId, agentId: meta.agentId, candidates, errorMessage: meta.errorMessage } }];

const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const p = $json;
const body = p.errorMessage
  ? { status: 'failed', errorMessage: p.errorMessage }
  : { status: 'completed', candidates: p.candidates };
const rawBody = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
return [{ json: { ...p, rawBody, timestamp, signature } }];

const crypto = require('crypto');
const secret = $vars.N8N_WEBHOOK_SECRET;
const timestamp = Date.now();
const p = $('Parse Candidates JSON').first().json;
const body = { input: { icpId: p.icpId }, output: { candidateCount: p.candidates.length }, status: p.errorMessage ? 'failure' : 'success' };
const rawBody = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
return [{ json: { agentId: p.agentId, rawBody, timestamp, signature } }];
